const searchSkills = `-- name: SearchSkills :many
SELECT slug::text AS slug, name, category
FROM skills
WHERE is_active
  AND (
    $1::text IS NULL
    OR name ILIKE '%' || $1::text || '%'
  )
ORDER BY
  CASE WHEN $1::text IS NULL THEN 0 ELSE -similarity(name, $1::text) END,
  name
LIMIT 20
`

type SearchSkillsRow struct {
	Slug     string
	Name     string
	Category string
}

func (q *Queries) SearchSkills(ctx context.Context, query *string) ([]SearchSkillsRow, error) {
	rows, err := q.db.Query(ctx, searchSkills, query)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []SearchSkillsRow{}
	for rows.Next() {
		var i SearchSkillsRow
		if err := rows.Scan(&i.Slug, &i.Name, &i.Category); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

